from fractions import Fraction

def rearrange_to(target, n):
    """First n terms of the greedy rearrangement of 1 - 1/2 + 1/3 - ...
    aimed at target, as Fractions."""
    target = Fraction(target)
    total, pos, neg, out = Fraction(0), 1, 2, []
    for _ in range(n):
        if total <= target:
            term = Fraction(1, pos)
            pos += 2
        else:
            term = Fraction(-1, neg)
            neg += 2
        total += term
        out.append(term)
    return out

def total_after(target, n):
    """The total of those n terms, as a float."""
    return float(sum(rearrange_to(target, n)))
